"use client";

import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Index from './pages/Index';
import { Toaster } from '@/components/ui/sonner';
import { useUiSounds } from '@/hooks/use-ui-sounds';

function App() {
  // Sons de survol/clic sur les éléments interactifs de toute l'interface
  // (voir src/hooks/use-ui-sounds.ts) - monté une seule fois ici.
  useUiSounds();

  return (
    <Router>
      <Routes>
        <Route path="/" element={<Index />} />
      </Routes>
      {/* Point de rendu de tous les messages de src/utils/toast.ts (showSuccess, showWarning…) :
          sans lui, ces appels ne s'affichaient nulle part. Thème forcé : l'interface est sombre
          et aucun ThemeProvider (next-themes) n'est monté. Ancré en bas à droite, au plus près du
          bord de l'écran (même logique que les autres panneaux flottants du chrome, cf.
          GCodePreviewBar/ModelStatusBox dans Index.tsx) plutôt qu'au centre. Même verre dépoli que
          ces panneaux (fond translucide + flou, pas de bordure) via toastOptions, le composant
          ui/sonner.tsx généré par shadcn restant lui-même intact. */}
      <Toaster
        theme="dark"
        position="bottom-right"
        // Même marge droite que le bouton Export (SliceSidebar.module.scss, right: 24px), et
        // décalé au-dessus de lui (~52px de haut + 24px de marge basse) pour ne jamais le
        // chevaucher ni chevaucher la barre de lecture G-code (GCodePreviewBar, ancrée à bottom-3).
        offset={{ bottom: '84px', right: '24px' }}
        // Permanentes : ne disparaissent jamais seules (cf. showEvent dans utils/toast.ts), seule
        // la croix de fermeture (closeButton) les retire.
        duration={Infinity}
        closeButton
        toastOptions={{
          style: {
            background: 'rgba(10, 15, 26, 0.25)',
            backdropFilter: 'blur(4px)',
            WebkitBackdropFilter: 'blur(4px)',
            border: 'none',
            borderRadius: '14px',
            boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3)',
            color: 'rgb(212, 212, 216)',
          },
          descriptionClassName: 'text-zinc-300',
        }}
      />
    </Router>
  );
}

export default App;

import { toast } from "sonner";

export const showSuccess = (message: string) => {
  toast.success(message);
};

export const showError = (message: string) => {
  toast.error(message);
};

export const showWarning = (message: string) => {
  toast.warning(message);
};

export const showLoading = (message: string) => {
  return toast.loading(message);
};

export const dismissToast = (toastId: string) => {
  toast.dismiss(toastId);
};

.toolbar {
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: auto;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);

  background: rgba(10, 15, 26, 0.25);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border: none;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  padding: 8px 16px;
  border-radius: 16px;
  width: 293px;
}

.button {
  display: flex;
  align-items: center;
  justify-content: center;

.bar {
  position: relative;
  flex: 0 0 80%;
  min-width: 0;
  height: 40px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 12px;
  border-radius: 14px;
  border: none;
  isolation: isolate;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  pointer-events: auto;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(10, 15, 26, 0.25);
    backdrop-filter: blur(4px);
--
// que .bar (fond translucide + flou) plutôt qu'un disque plein ou lumineux. Pas de halo externe :
// seule une ombre portée neutre la détache du rail, comme .playButton au repos.
// `pointer-events: auto` (plutôt que `none` comme avant) : seul CE point doit déclencher le son
// de survol des éléments interactifs (cf. data-ui-sound en JSX), pas le reste de la piste — il lui
// faut donc être la cible réelle du survol. Le drag depuis n'importe où sur .track continue de
// fonctionner malgré ça : `onPointerDown`/`onPointerMove` restent déclenchés par la remontée
// normale de l'événement jusqu'au parent.
.trackHandle {
  position: absolute;
  top: 50%;
  width: 10px;
  height: 18px;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.18);
  border: 1px solid rgba(255, 255, 255, 0.3);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  box-shadow: 0 2px 6px 0 rgba(0, 0, 0, 0.4);
  transform: translate(-50%, -50%);
  pointer-events: auto;
  cursor: pointer;

  const label = SPACE_LABELS[space];
  const sound = SPACE_SOUNDS[space];
  if (sound) playUiSound(sound);
  if (bottomToolbarRef.current) {
    const rect = bottomToolbarRef.current.getBoundingClientRect();
    const computedRadius = parseFloat(getComputedStyle(bottomToolbarRef.current).borderTopLeftRadius) || 22;
    // `x`/`y` ne sont pas lisibles depuis le DOM (ce sont des translate posés par
    // framer-motion, pas une position absolue) : on reprend ceux du mode qu'on est en
    // train de quitter, calculés par la même table que `targetGeometry` ci-dessous.
    setFromGeometry({
      x: targetGeometry.x,
      y: targetGeometry.y,
      width: rect.width,
      height: rect.height,
      borderRadius: computedRadius,
    });
  }
  window.dispatchEvent(new CustomEvent('apex-space-transition', { detail: { label, onCovered } }));
};

const handleTopTabClick = (tabName: 'box' | 'settings' | 'developer' | 'params') => {
  if (tabName === 'settings' && !isModeling) {
    // Signale DÈS LE CLIC — avant même que le rideau plein écran ne commence à monter, pas
    // seulement une fois l'écran couvert (`onCovered`, ~900ms plus tard) — que les éléments sans
    // place dans l'espace Modélisation (ModelStatusBox, panneau du bas de Prévisualisation)
    // doivent commencer à disparaître : ce fondu-glissement doit être visible EN TRANSPARENCE À
    // TRAVERS le rideau (z-index 1000+ pour ces éléments, contre 30 pour le rideau), jamais
    // caché derrière lui comme le vrai changement d'onglet (`onTabChange`, lui, reste dans
    // `onCovered` ci-dessous : le panneau Modélisation ne doit apparaître qu'une fois l'écran
    // couvert).
    window.dispatchEvent(new CustomEvent('apex-entering-modeling'));
  } else if (tabName !== 'settings' && isModeling) {
    // Symétrique : le contenu du panneau Modélisation disparaît en cascade dès le clic, avant
    // que sa forme ne commence à se déformer (à `onCovered`, cf. ModelingSidebar).
    window.dispatchEvent(new CustomEvent('apex-leaving-modeling'));
  }
  playSpaceTransition(tabName, () => {
    setActiveTool('select');
    onTabChange(tabName);
    setIsPreviewActive(false);
    window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: false } }));
  });
};

const handleToolClick = (tool: 'select' | 'move' | 'rotate' | 'scale' | 'texture') => {
  const newTool = activeTool === tool ? 'select' : tool;
  setActiveTool(newTool);
  window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
};

/**
 * Bascule animée vers l'espace Prévisualisation (rideau + déformation de la pilule), factorisée
 * hors de `handleLayerClick` pour être aussi déclenchée par le dépôt d'un fichier G-code en
 * Préparation (cf. l'écouteur `drop` plus bas) — même geste que le clic sur l'icône Prévisualisation,
 * simplement déclenché autrement. `pendingFile`, s'il est fourni, est réémis (`apex-gcode-loaded`
 * en pointillé via `apex-entering-preview-with-file`) une fois l'écran couvert, PAS avant : au
 * moment du dépôt, l'espace Prévisualisation n'a pas encore son hook de lecture actif
 * (`useGCodePreview(isPreviewActive)` dans Index.tsx), lequel n'écoute le dépôt/chargement que
 * lorsque `active` — le charger avant ce basculement n'aurait donc aucun effet.
 */
const enterPreview = (pendingFile?: File) => {
  // Depuis Modélisation : même signal au clic que handleTopTabClick (cf. apex-leaving-modeling).
  if (isModeling) window.dispatchEvent(new CustomEvent('apex-leaving-modeling'));
  // L'ancien fondu séquencé des panneaux (avant le rideau plein écran) n'a plus de raison
  // d'être : le rideau masque déjà tout pendant que ce switch se produit, donc tout bascule
  // d'un coup sous le voile plutôt qu'en deux temps visibles.
  playSpaceTransition('layers', () => {
    setActiveTool('layers');
    // Prévisualisation est un sous-mode du slicer (Préparation), jamais de la
    // Modélisation : sans ce `onTabChange`, entrer en Prévisualisation depuis
    // Modélisation laissait `activeTab` sur 'settings', et donc le bouton
    // "Modélisation" restait actif (cyan) par-dessus "Prévisualisation". Le second argument
    // signale spécifiquement ce cas-là à Index.tsx (venant de Modélisation, vers
    // Prévisualisation et non vers Préparation), pour qu'il joue le bon morph de sortie.
    onTabChange('box', true);
    setIsPreviewActive(true);
    window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'layers' } }));
    window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: true } }));
    // Dispatché en DERNIER, une fois `apex-preview-toggled` déjà parti : useGCodePreview
    // (Index.tsx) doit être passé à `active` avant de recevoir le fichier, sans quoi son
    // écouteur de dépôt (qui double aussi comme point d'entrée de chargement, cf.
    // use-gcode-preview.ts) ignorerait l'événement.
    if (pendingFile) {
      window.dispatchEvent(new CustomEvent('apex-entering-preview-with-file', { detail: { file: pendingFile } }));
    }
  });
};

const handleLayerClick = () => {
  const entering = activeTool !== 'layers';

  if (entering) {
    enterPreview();
  } else {
    playSpaceTransition('box', () => {
      setActiveTool('select');
      setIsPreviewActive(false);
      window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'select' } }));
      window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: false } }));
    });
  }
};

// Dépôt d'un fichier G-code n'importe où dans la fenêtre pendant qu'on est en Préparation (hors
// Prévisualisation, hors Modélisation) : bascule automatiquement vers l'espace Prévisualisation,
// avec la même animation que le clic sur son icône, puis charge le fichier une fois l'écran
// découvert (cf. `enterPreview`). Un simple survol (dragenter/dragover) sans dépôt ne déclenche
// rien — jamais de bascule sur un simple passage de fichier au-dessus de la fenêtre.
useEffect(() => {
  if (isPreviewActive || isModeling) return;
  const hasFiles = (e: DragEvent) => !!e.dataTransfer?.types.includes('Files');
  const onDragOver = (e: DragEvent) => {
    if (!hasFiles(e)) return;
    e.preventDefault();
    if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
  };
  const onDrop = (e: DragEvent) => {
    if (!hasFiles(e)) return;
    const file = e.dataTransfer?.files?.[0];
    if (!file || !GCODE_FILE_EXT.test(file.name)) return;
    e.preventDefault();
    enterPreview(file);
  };
  window.addEventListener('dragover', onDragOver);
  window.addEventListener('drop', onDrop);
  return () => {
    window.removeEventListener('dragover', onDragOver);
    window.removeEventListener('drop', onDrop);
  };
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [isPreviewActive, isModeling]);

useEffect(() => {
  const handleKeyDown = (e: KeyboardEvent) => {
    const target = e.target as HTMLElement | null;
    if (target && (['INPUT', 'TEXTAREA'].includes(target.tagName) || target.isContentEditable)) {
      return;
    }

    const key = e.key.toLowerCase();
    if (key === 'm') {
      const newTool = activeTool === 'move' ? 'select' : 'move';
      setActiveTool(newTool);
      window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
    } else if (key === 'r') {
      const newTool = activeTool === 'rotate' ? 'select' : 'rotate';
      setActiveTool(newTool);
      window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
    } else if (key === 's') {
      const newTool = activeTool === 'scale' ? 'select' : 'scale';
      setActiveTool(newTool);
      window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
    } else if (key === 't') {
      const newTool = activeTool === 'texture' ? 'select' : 'texture';
      setActiveTool(newTool);
      window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
    } else if (key === 'escape') {
      setActiveTool('select');
      window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'select' } }));
    }
  };

import * as React from "react";

import type { ToastActionElement, ToastProps } from "@/components/ui/toast";

const TOAST_LIMIT = 1;
const TOAST_REMOVE_DELAY = 1000000;

type ToasterToast = ToastProps & {
  id: string;
  title?: React.ReactNode;
  description?: React.ReactNode;
  action?: ToastActionElement;
};

const _actionTypes = {
  ADD_TOAST: "ADD_TOAST",
  UPDATE_TOAST: "UPDATE_TOAST",
  DISMISS_TOAST: "DISMISS_TOAST",
  REMOVE_TOAST: "REMOVE_TOAST",
} as const;

let count = 0;

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER;
  return count.toString();
}

type ActionType = typeof _actionTypes;

type Action =
  | {
      type: ActionType["ADD_TOAST"];
      toast: ToasterToast;
    }
  | {
      type: ActionType["UPDATE_TOAST"];
      toast: Partial<ToasterToast>;
    }
  | {
      type: ActionType["DISMISS_TOAST"];
      toastId?: ToasterToast["id"];
    }
  | {
      type: ActionType["REMOVE_TOAST"];
      toastId?: ToasterToast["id"];
    };

interface State {
  toasts: ToasterToast[];
}

const toastTimeouts = new Map<string, ReturnType<typeof setTimeout>>();

const addToRemoveQueue = (toastId: string) => {
  if (toastTimeouts.has(toastId)) {
    return;
  }

  const timeout = setTimeout(() => {

  ? renderPrecisionMm[colorBy] ?? null
  : null;

// apex-gcode-color-by porte AUSSI la précision courante du mode qui devient actif (mémorisée par
// mode comme le scope) : reconstruit la géométrie au bon niveau de détail dès qu'on bascule vers
// un mode déjà réglé, sans attendre un nouveau glisser du curseur de précision.
useEffect(() => {
  window.dispatchEvent(new CustomEvent('apex-gcode-color-by', {
    detail: { mode: colorBy, scope: activeColorByScope ?? undefined },
  }));
  window.dispatchEvent(new CustomEvent('apex-gcode-render-precision', { detail: { mm: activeRenderPrecisionMm } }));
  // activeColorByScope/activeRenderPrecisionMm sont dérivés à chaque rendu (pas des states à
  // part) : les comparer par valeur éviterait un effet à chaque rendu, mais colorByScopes/
  // renderPrecisionMm/fileInfo eux-mêmes ne changent que sur une vraie action utilisateur
  // (glisser un curseur, cocher la case, charger un fichier) — donc aussi peu fréquent qu'un
  // state dédié l'aurait été, sans la complexité d'une comparaison profonde.
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [colorBy, colorByScopes, renderPrecisionMm, fileInfo]);

const setColorBy = useCallback((mode: ColorByMode) => setColorByState(mode), []);

/** Règle la portée (curseurs min/max) et/ou l'écrêtage hors-portée du mode continu `mode`,
 * mémorisée indépendamment des autres modes pour le reste de la session sur ce fichier. */
const setColorByScope = useCallback((mode: ContinuousColorByMode, scope: ColorByScope) => {
  setColorByScopes((prev) => ({ ...prev, [mode]: scope }));
}, []);

/** Règle la précision de rendu (longueur max de sous-segment, mm) du mode continu `mode` — à
 * n'appeler qu'au RELÂCHEMENT du curseur (jamais pendant le glisser) : reconstruit la géométrie
 * des cordons (cf. gcodeLayer.ts setRenderPrecision), coûteux à répéter à chaque pixel glissé. */
const setRenderPrecision = useCallback((mode: ContinuousColorByMode, mm: number | null) => {
  setRenderPrecisionMmState((prev) => ({ ...prev, [mode]: mm ?? undefined }));
}, []);

useEffect(() => {
  window.dispatchEvent(new CustomEvent('apex-gcode-show-full-head', { detail: { show: showFullHead } }));
}, [showFullHead]);

// Horloge de lecture : avance le temps machine (durées réelles des mouvements, cf.
// `ParsedGCode.times`) à `speed` × le temps réel, le reconvertit en index de mouvement `t`,
// pousse chaque image au viewport et rafraîchit l'état React à ~20 Hz seulement.
useEffect(() => {
  if (!isPlaying) return;
  const parsed = parsedRef.current;
  if (!parsed) return;
  const last = parsed.moves.length - 1;
  let raf = 0;
  let prev = performance.now();
  let sinceUiSync = 0;
  const step = (now: number) => {
    const dt = (now - prev) / 1000;
    prev = now;
    const s = timeAtIndex(parsed.times, tRef.current) + speed * dt;
    tRef.current = Math.min(last, indexAtTime(parsed.times, s));
    dispatchTime(tRef.current);
    sinceUiSync += dt;
    if (tRef.current >= last) {
      setT(last);
      setIsPlaying(false);
      return;
    }
    if (sinceUiSync > 1 / 20) {
      sinceUiSync = 0;
      setT(tRef.current);
    }
    raf = requestAnimationFrame(step);
  };
  raf = requestAnimationFrame(step);
  return () => cancelAnimationFrame(raf);
}, [isPlaying, speed]);

/** Parse et affiche un G-code ; renvoie le résultat, ou null (erreur déjà signalée). */
const loadText = (text: string, name: string): ParsedGCode | null => {
  let parsed: ParsedGCode;
  try {
    parsed = parseGCode(text);
  } catch {
    showError('Impossible de lire ce fichier G-code.');
    return null;
  }
  if (parsed.moves.length < 2) {
    showError('Aucune trajectoire exploitable dans ce fichier.');
    return null;
  }

  parsedRef.current = parsed;
  currentRef.current = { text, name };
  const last = parsed.moves.length - 1;
  tRef.current = last;
  setIsPlaying(false);
  setT(last);
  setColorByState('lineType');
  setColorByScopes({});
  setRenderPrecisionMmState({});
  window.dispatchEvent(new CustomEvent('apex-gcode-loaded', { detail: { parsed } }));

  setFileInfo({
    name,
    kind: parsed.kind,
    lineStats: parsed.lineStats,
    totalTime: parsed.times[parsed.times.length - 1],
    generator: parsed.generator,
    printer: parsed.printer,
    nonPlanar: parsed.nonPlanar,
    conversion: parsed.conversion,
    moves: parsed.moves.length,
    extruding: parsed.extrudingCount,
    minZ: parsed.minZ,
    maxZ: parsed.maxZ,
    minC: parsed.minC,
    maxC: parsed.maxC,
    colorByRanges: parsed.ranges,
  });
  return parsed;
};

const loadFile = async (file: File) => {
  if (!GCODE_FILE_EXT.test(file.name)) {
    showError('Format non supporté. Utilisez un fichier .gcode, .gco, .g ou .ngc.');
    return;
  }
  setIsLoading(true);
  const text = await file.text().catch(() => null);
  const parsed = text === null ? null : loadText(text, file.name);
  setIsLoading(false);
  if (!parsed) return;

  // Nouveau fichier : il devient la source d'une éventuelle conversion polaire (s'il est 3 axes).
  sourceRef.current = parsed.kind === 'cartesian'
    ? { text: text!, name: file.name, parsed }
    : null;
  setConversion(IDLE_CONVERSION);
  setOffPlateHighlight(false);

  // Un C qui accumule les tours est normal dans un fichier converti (le plateau suit la pièce).
  if (parsed.kind === 'polar' && !parsed.conversion && parsed.maxC - parsed.minC > SUSPICIOUS_C_RANGE_DEG) {
    showWarning(`L'angle C dérive sur ${(parsed.maxC - parsed.minC).toFixed(0)}° : ce fichier vient probablement d'une version boguée du générateur.`);
  } else {
    showSuccess(`G-code chargé : ${parsed.moves.length} mouvements.`);
  }
};

/** Convertit la source 3 axes en G-code polaire Apex (script Python de l'application de bureau)
 * et affiche le résultat ; la source est conservée pour reconvertir dans l'autre mode. */
const convert = async (mode: ConversionMode, dropOffPlate: boolean) => {
  const source = sourceRef.current;
  if (!source || conversion.status === 'running') return;
  // Traits hors plateau déjà surlignés en rouge (confirmation dans GCodeConversionCard, s'il y en
  // avait — cf. `hasOffPlate`) : restent affichés, mais clignotent pendant que la conversion qui
  // va les retirer tourne, pour signaler qu'un changement est en cours sans les faire disparaître
  // (cf. GCodeConversionCard.answerOffPlate, qui ne les éteint plus non plus). Sans traits hors

