## 2. Store shape (`src/utils/notificationStore.ts`)

```ts
export type NotificationVariant = 'success' | 'error' | 'warning' | 'loading';

export interface NotificationItem {
  id: string;
  variant: NotificationVariant;
  message: string;
  createdAt: number; // Date.now(), used only for stable ordering
}

type Listener = (items: NotificationItem[]) => void;

let items: NotificationItem[] = [];
// Index into `items` (by id) of the notification currently pinned to front by
// the wheel gesture. `null` = no manual override, front = most recent (last
// pushed) — see §5 for how this interacts with new arrivals.
let frontId: string | null = null;
const listeners = new Set<Listener>();

function emit() {
  const snapshot = items.slice();
  listeners.forEach((l) => l(snapshot));
}

let uid = 0;
function genId() {
  uid += 1;
  return `ntf-${Date.now()}-${uid}`;
}

export function pushNotification(variant: NotificationVariant, message: string): string {
  const id = genId();
  items = [...items, { id, variant, message, createdAt: Date.now() }];
  frontId = id; // a new notification always becomes the front card
  emit();
  return id;
}

/** Used by showLoading's returned id + dismissToast, and by the × button. */
export function removeNotification(id: string): void {
  const idx = items.findIndex((n) => n.id === id);
  if (idx === -1) return;
  items = items.filter((n) => n.id !== id);
  if (frontId === id) frontId = null; // stack re-derives front (see selector)
  emit();
}

/** Called by NotificationStack's wheel handler. */
export function setFrontNotification(id: string): void {
  if (!items.some((n) => n.id === id)) return;
  frontId = id;
  emit();
}

export function subscribe(listener: Listener): () => void {
  listeners.add(listener);
  listener(items.slice());
  return () => listeners.delete(listener);
}

export function getFrontId(): string | null {
  return frontId;
}
```

Notes:
- `loading` variant is kept only because `showLoading`/`dismissToast` must keep
  working (grep shows these two are currently unused at call sites, but they are
  part of the public `toast.ts` API and must not regress). It renders like the
  others but conventionally callers immediately follow up with
  `dismissToast(id)` once work finishes — no spinner infra needed beyond a
  small rotating icon in the card if desired; not a requirement, keep it simple
  (static "loading" styling, e.g. a subtle pulsing dot) since these permanent
  cards have no timer to race against.
- Ordering is push order (`items` array, oldest first, newest last). The stack
  always visually derives "who's on top" from `frontId ?? items[items.length-1]?.id`
  (see §4), so a fresh `pushNotification` always naturally becomes front without
  extra logic in the component.

